import{_ as a,o as i,c as l,a8 as t}from"./chunks/framework.BppdKxCY.js";const m=JSON.parse('{"title":"EP.71 百万数据点的可视化密码","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.71-iot-time-series.md","filePath":"comics/EP.71-iot-time-series.md","lastUpdated":1793706365000}'),o={name:"comics/EP.71-iot-time-series.md"};function r(s,e,n,h,c,d){return i(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="ep-71-百万数据点的可视化密码" tabindex="-1">EP.71 百万数据点的可视化密码 <a class="header-anchor" href="#ep-71-百万数据点的可视化密码" aria-label="Permalink to &quot;EP.71 百万数据点的可视化密码&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../97-iot-time-series">97-iot-time-series.md</a>（97.2 降采样 / 97.3 告警 / 97.4 缓冲 / 97.5 对齐）· 示例：<code>examples/97-01-iot-time-series.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：百万级数据点直接渲染，浏览器卡死。</li><li><strong>第 2 格</strong>：码叔揭秘降采样——平均聚合看趋势，LTTB 保留峰值形状。</li><li><strong>第 3 格</strong>：像素酱实证滚动窗口告警防抖 + 实时缓冲合并渲染。</li><li><strong>第 4 格</strong>：码叔结案——多设备时间对齐与时序数据库存储策略。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-海量点的问题" tabindex="-1">第 1 格 · 海量点的问题 <a class="header-anchor" href="#第-1-格-·-海量点的问题" aria-label="Permalink to &quot;第 1 格 · 海量点的问题&quot;">​</a></h3><ul><li>屏幕只有约 2000 像素宽，画百万个点无意义；</li><li>SVG 渲染大量元素会爆炸，应用 Canvas；</li><li>必须降采样到可视点数。</li></ul><h3 id="第-2-格-·-降采样算法" tabindex="-1">第 2 格 · 降采样算法 <a class="header-anchor" href="#第-2-格-·-降采样算法" aria-label="Permalink to &quot;第 2 格 · 降采样算法&quot;">​</a></h3><ul><li>平均聚合：按时间窗口取均值，适合看趋势但丢峰值；</li><li>LTTB：选三角形面积最大的点，保留折线形状（峰值不丢）；</li><li>服务端 <code>GROUP BY time()</code> 聚合，客户端 LTTB 再降。</li></ul><h3 id="第-3-格-·-告警与缓冲" tabindex="-1">第 3 格 · 告警与缓冲 <a class="header-anchor" href="#第-3-格-·-告警与缓冲" aria-label="Permalink to &quot;第 3 格 · 告警与缓冲&quot;">​</a></h3><ul><li>连续 N 点超阈值才告警，过滤毛刺；</li><li>高频推送先缓冲，500ms~1s 合并 flush，减少渲染。</li></ul><h3 id="第-4-格-·-时间对齐与存储" tabindex="-1">第 4 格 · 时间对齐与存储 <a class="header-anchor" href="#第-4-格-·-时间对齐与存储" aria-label="Permalink to &quot;第 4 格 · 时间对齐与存储&quot;">​</a></h3><ul><li>多设备对齐到统一时间网格（最近邻/线性插值）；</li><li>时序数据库（InfluxDB/TDengine），保留策略：原始7天、分钟级1年。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../97-iot-time-series#_97-7-本章避坑清单">《97.7 本章避坑清单》</a></p></blockquote><ol><li>百万点直接画 → 降采样+Canvas；</li><li>单点毛刺告警 → 连续 N 点才触发；</li><li>每个点 setState → 缓冲合并渲染。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>平均聚合和 LTTB 降采样的区别？——<strong>平均聚合看趋势丢峰值，LTTB 保留形状不丢峰值</strong>。</li><li>为什么告警要用连续 N 点超阈值？——<strong>过滤传感器瞬时毛刺，减少误报</strong>。</li><li>多设备数据时间不一致怎么处理？——<strong>对齐到统一时间网格，用最近邻或线性插值</strong>。</li></ol>',18)])])}const _=a(o,[["render",r]]);export{m as __pageData,_ as default};
